('广东省博物馆', '博物馆', '广东省', '广州市', '天河区珠江东路2号', 113.3910000, 23.1190000, '广东省博物馆是国家一级博物馆，馆藏丰富，涵盖历史、艺术、自然等多个领域。', '09:00-17:00（周一闭馆）', 0.00, '["小学","初中","高中"]', '["历史","文化","艺术"]', '["岭南文化","广府历史","海上丝绸之路"]', '["https://example.com/gdmuseum1.jpg"]', 1),

('广州科学中心', '科技馆', '广东省', '广州市', '番禺区大学城科普路168号', 113.3760000, 23.0470000, '广州科学中心是广东省重点建设项目，集科普教育、科技展览于一体。', '09:30-16:30（周一闭馆）', 60.00, '["小学","初中"]', '["科技","自然","探索"]', '["物理实验","生命科学","航空航天"]', '["https://example.com/gzscience1.jpg"]', 1),

('黄埔军校旧址', '基地', '广东省', '广州市', '黄埔区长洲岛军校路170号', 113.4580000, 23.0920000, '黄埔军校是中国近代史上著名的军事学校，培养了大批优秀军事人才。', '09:00-17:00', 0.00, '["初中","高中"]', '["红色教育","历史","爱国"]', '["近代史","军事历史","革命精神"]', '["https://example.com/huangpu1.jpg"]', 1),

('广州动物园', '景区', '广东省', '广州市', '越秀区先烈中路120号', 113.2780000, 23.1480000, '广州动物园是中国三大城市动物园之一，拥有各类动物460余种。', '08:00-18:00', 20.00, '["小学","初中"]', '["自然","生物","探索"]', '["动物分类","生态保护","生物多样性"]', '["https://example.com/gzzoo1.jpg"]', 1),

('陈家祠', '博物馆', '广东省', '广州市', '荔湾区中山七路恩龙里34号', 113.2450000, 23.1260000, '陈家祠是广东现存规模最大、装饰最精美的祠堂建筑，是岭南建筑艺术的典范。', '08:30-17:30', 10.00, '["小学","初中","高中"]', '["历史","文化","艺术","建筑"]', '["岭南建筑","民间工艺","宗族文化"]', '["https://example.com/chenjiaci1.jpg"]', 1),

('南越王博物院', '博物馆', '广东省', '广州市', '越秀区解放北路867号', 113.2620000, 23.1350000, '南越王博物院是在南越国宫署遗址和南越王墓原址上建立的博物馆。', '09:00-17:30（周一闭馆）', 10.00, '["初中","高中"]', '["历史","考古","文化"]', '["秦汉历史","考古发现","南越国"]', '["https://example.com/nanyue1.jpg"]', 1),

('华南植物园', '景区', '广东省', '广州市', '天河区天源路1190号', 113.3640000, 23.1850000, '中国科学院华南植物园是我国历史最悠久的植物学研究和植物保育机构之一。', '07:30-17:30', 20.00, '["小学","初中","高中"]', '["自然","生物","科技"]', '["植物分类","生态系统","植物保护"]', '["https://example.com/hnsplant1.jpg"]', 1),

('珠江夜游', '景区', '广东省', '广州市', '天河区珠江新城', 113.3280000, 23.1150000, '珠江夜游是广州最具特色的旅游项目之一，可欣赏珠江两岸美丽夜景。', '18:30-22:00', 88.00, '["小学","初中","高中"]', '["文化","城市","艺术"]', '["城市发展","建筑艺术","珠江文化"]', '["https://example.com/zhujiang1.jpg"]', 1);

