INSERT INTO `route` (`name`, `description`, `days`, `price`, `suitable_grades`, `themes`, `cover_image`, `source`, `view_count`, `like_count`, `status`) VALUES
('广州历史文化两日研学', '深入了解广州千年历史，感受岭南文化魅力。行程包含广东省博物馆、陈家祠、南越王博物院等著名历史文化景点。', 2, 380.00, '["初中","高中"]', '["历史","文化"]', 'https://example.com/route1.jpg', 'manual', 1256, 89, 1),

('科技探索一日营', '走进广州科学中心，体验科技的神奇魅力。适合对科学有浓厚兴趣的中小学生参加。', 1, 198.00, '["小学","初中"]', '["科技","探索"]', 'https://example.com/route2.jpg', 'manual', 892, 56, 1),

('红色教育主题研学', '参观黄埔军校旧址，学习革命先辈的光荣事迹，传承红色基因，培养爱国情怀。', 1, 150.00, '["初中","高中"]', '["红色教育","历史","爱国"]', 'https://example.com/route3.jpg', 'manual', 678, 45, 1),

('自然生态探索营', '参观广州动物园和华南植物园，认识各种动植物，了解生态保护知识。', 2, 280.00, '["小学","初中"]', '["自然","生物","生态"]', 'https://example.com/route4.jpg', 'manual', 534, 32, 1),

('岭南文化深度游', '全面体验岭南文化，从建筑到美食，从历史到艺术，深入了解广府文化的独特魅力。', 3, 580.00, '["初中","高中"]', '["文化","艺术","历史"]', 'https://example.com/route5.jpg', 'manual', 423, 28, 1);

